def quick_sort(lst):
    length = len(lst)
    if length <= 1:
        return lst
    else:
        # 选择中间元素作为枢轴
        pivot = lst.pop(length // 2)

    elements_greater = []
    elements_smaller = []

    for element in lst:
        # 如果元素大于枢轴，添加到elements_greater列表
        if element > pivot:
            elements_greater.append(element)
        # 否则，添加到elements_smaller列表
        else:
            elements_smaller.append(element)

    # 递归调用quick_sort函数，对elements_smaller和elements_greater列表进行排序
    return quick_sort(elements_smaller) + [pivot] + quick_sort(elements_greater)

# 接受整数输入并将其转换为列表
data_list = list(map(int, input().split()))

sorted_list = quick_sort(data_list)
print(sorted_list)
